@startuml

class Location {
  + Address : string
}

class Driver {
  + FirstName : string
  + LastName : string
}

class Vehicle {
  + VehicleNumber : string
}

class Truck extends Vehicle {
  + Weight : float
}

class Car extends Vehicle {
  + Seats : int
}

class Van extends Vehicle {}

class Order {
  + ExecutionDate : date
}

Location "1" -- "*" Driver
Location "1" -- "*" Vehicle
Driver "1" -- "0..1" Order
Driver "1" -- "0..*" Vehicle
Order "*" -- "1" Location : Origin
Order "*" -- "1" Location : Destination
Order "*" -- "1..*" Driver

@enduml

